// Sound effects. The WAV files are generated by scripts/generate-sounds.mjs into assets/sounds/ (T-31); until
// then playback is a no-op so that the screens can already name their sounds.
export type SoundName = 'tick' | 'drop' | 'clear' | 'combo' | 'shoot' | 'pop' | 'over' | 'star' | 'coin' | 'levelup' | 'refused';

export const SOUND_NAMES: readonly SoundName[] = ['tick', 'drop', 'clear', 'combo', 'shoot', 'pop', 'over', 'star', 'coin', 'levelup', 'refused'];

let player: ((name: SoundName) => void) | null = null;

/** Installs the real player (expo-audio) once the sound assets are bundled. */
export function setSoundPlayer(impl: ((name: SoundName) => void) | null): void {
  player = impl;
}

export function playSound(name: SoundName): void {
  player?.(name);
}
